SELECT AVG(x2.v2860) OVER x0, NTH_VALUE(x2.v2861, 'a') OVER (), SUM(DISTINCT x1.v2988) FROM v2987 AS x1 LEFT JOIN v2859 AS x2 ON (x1.v2988 = x1.v2988) WHERE x1.v2988 = 'test' AND x1.v2988 LIKE 't%' AND x1.v2988 = 'v' GROUP BY x1.v2988 WINDOW x3 AS (PARTITION BY x2.v2860 ORDER BY CASE WHEN x1.v2988 IS NULL THEN 1 ELSE 0 END, x2.v2862) ORDER BY CASE WHEN 'test' IS NULL THEN 1 ELSE 0 END, 'test', CASE WHEN 'testtest' IS NULL THEN 1 ELSE 0 END, 'testtest'